// Guarda os segmentos, as PALAVRAS (para o karaokê) e o idioma detectado.
const r = $input.first().json;
const segs = r.segments || [];
const words = r.words || [];
const idioma = (r.language || '').toString().toLowerCase();

const linhas = segs.map(s => `[${s.start.toFixed(1)}-${s.end.toFixed(1)}] ${s.text.trim()}`);
const duracaoTotal = segs.length ? segs[segs.length - 1].end : 0;

// Teto de 5: TikTok zera views acima disso, e 5 uploads cabem na cota do YouTube.
const META_MIN = 2;
const META_MAX = 5;
const alvoCortes = Math.max(META_MIN, Math.min(META_MAX, Math.floor(duracaoTotal / 150)));

// O Whisper devolve o idioma escrito por extenso em inglês ("portuguese").
const ehPortugues = /^(pt|portug)/.test(idioma) || idioma === '';

if (!words.length) {
  // sem palavras não há karaokê — não é erro, só cai para legenda por segmento
  console.log('Whisper não devolveu "words": a legenda vai sair por segmento.');
}

return [{
  json: {
    transcricao_com_tempo: linhas.join('\n'),
    duracao_total: duracaoTotal,
    duracao_minutos: +(duracaoTotal / 60).toFixed(1),
    alvo_cortes: alvoCortes,
    idioma,
    eh_portugues: ehPortugues,
    segmentos: segs.map(s => ({ start: s.start, end: s.end, text: (s.text || '').trim() })),
    palavras: words.map(p => ({ word: (p.word || '').trim(), start: p.start, end: p.end }))
  }
}];

// ============================================================
// FUTEBOL — para cada corte:
//  1) ALINHA início e fim aos limites de fala (nunca corta assunto no meio)
//  2) escreve um .ass com: selo de parte, hook fixo, LEGENDA KARAOKÊ
//     palavra por palavra e pergunta final
//  3) monta o comando ffmpeg (9:16, fundo desfocado, tudo queimado)
// ============================================================

const raw = ($json.output ?? $json.text ?? '').toString();
const match = raw.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('Não encontrei JSON na resposta do agente: ' + raw.slice(0, 300));
}
const parsed = JSON.parse(match[0]);
if (!Array.isArray(parsed.cortes) || parsed.cortes.length === 0) {
  throw new Error('Resposta do agente não trouxe a chave "cortes" como lista.');
}

const videoId = $('Drive: novo vídeo').first().json.id;
const dadosTransc = $('Transcrição pronta').first().json;
const segmentos = dadosTransc.segmentos || [];
const palavras  = dadosTransc.palavras  || [];
const duracaoTotal = Number(dadosTransc.duracao_total) || 0;
const foiTraduzido = !!dadosTransc.traduzido;

const PASTA = '/home/node/files';
const PASTA_FONTES = '/opt/fonts';

// --- duração ------------------------------------------------
const MIN_DURACAO = 75;
const MAX_DURACAO = 165;
const FOLGA_FIM = 1.2;

// --- legenda de fala ----------------------------------------
// Karaokê palavra por palavra só funciona no idioma ORIGINAL: traduzir
// muda a quantidade e a ordem das palavras e destrói o tempo por palavra.
// Vídeo traduzido cai para legenda por segmento, sem karaokê.
const LEGENDA_FALA = true;
const KARAOKE_MAX_PALAVRAS = 3;
const KARAOKE_MAX_CHARS = 17;   // 1 linha em 1080px com fonte 64
const KARAOKE_PAUSA_QUEBRA = 0.6;
const KARAOKE_SOBRA = 0.12;
const LEGENDA_MAX_CHARS_SEG = 42;  // modo traduzido: teto de 2 linhas na tela
const LEGENDA_MIN_SEG = 0.7;       // duração mínima de um pedaço de legenda

// --- textos na tela -----------------------------------------
const TEXTO_TOPO_FIXO = true;
const HOOK_ATE = 4.0;
const PERGUNTA_ANTES_FIM = 6.0;
// com legenda de fala na tela o texto do meio some: seria poluição
const MOSTRAR_TEXTO_MEIO = false;
const MEIO_INICIO_PCT = 0.42;
const MEIO_DURACAO = 4.5;

// --- estética -----------------------------------------------
const LARGURA = 1080;
const ALTURA = 1920;
const FONTE_NOME = 'DejaVu Sans';
const FONT_HOOK = 104;
const FONT_TITULO = 78;
const FONT_FALA = 64;      // karaokê (1 linha)
const FONT_FALA_SEG = 56;  // legenda traduzida (até 2 linhas)
const FONT_MEIO = 72;
const FONT_PERGUNTA = 68;
const FONT_PARTE = 42;
const TOPO_TEXTO = 235;
const TOPO_PARTE = 145;
const BAIXO_FALA = 500;      // legenda de fala: acima da zona de UI (484px)
const BAIXO_PERGUNTA = 680;  // pergunta: logo acima da legenda de fala
const BAIXO_MEIO = 680;
const COR_HOOK = '&H0000FFFF';       // amarelo
const COR_TITULO = '&H00FFFFFF';
const COR_FALA_DITA = '&H0000FFFF';  // palavra já falada — amarelo
const COR_FALA_ANTES = '&H00FFFFFF'; // palavra ainda não falada — branco
// sem karaokê a legenda sai branca: dois amarelos na tela competiriam com o hook
const COR_MEIO = '&H0000FFFF';
const COR_PERGUNTA = '&H00FFFFFF';
const CAIXA = 'B4';
const BLUR_FUNDO = 28;
const MOSTRAR_SELO_PARTE = true;
// --- animação -----------------------------------------------
const FADE_ENTRA = 250;
const FADE_SAI = 250;
const POP_HOOK = true;
const POP_ESCALA = 92;
const POP_MS = 220;
// ------------------------------------------------------------

const usarKaraoke = LEGENDA_FALA && !foiTraduzido && palavras.length > 0;

if (duracaoTotal && duracaoTotal < MIN_DURACAO) {
  throw new Error(
    `O vídeo tem só ${duracaoTotal.toFixed(0)}s — é curto demais para cortes de ${MIN_DURACAO}s.`
  );
}

// ============================================================
// ALINHAMENTO AO FIM DE FRASE
// ============================================================
function fechaIdeia(txt) {
  return /[.!?…]["'”’)\]]?\s*$/.test((txt || '').trim());
}
function comecaFrase(indice) {
  if (indice === 0) return true;
  return fechaIdeia(segmentos[indice - 1].text);
}
function alinharInicio(alvo, minimo) {
  const cands = segmentos
    .map((s, i) => ({ start: s.start, novaFrase: comecaFrase(i) }))
    .filter(s => s.start >= minimo - 0.01);
  if (!cands.length) return Math.max(alvo, minimo);
  const antes = cands.filter(s => s.start <= alvo);
  const frasesAntes = antes.filter(s => s.novaFrase);
  if (frasesAntes.length) return frasesAntes[frasesAntes.length - 1].start;
  if (antes.length) return antes[antes.length - 1].start;
  const frase = cands.find(s => s.novaFrase);
  return frase ? frase.start : cands[0].start;
}
function alinharFim(alvo, minAbs, maxAbs) {
  const dentro = segmentos.filter(s => s.end >= minAbs && s.end <= maxAbs);
  if (!dentro.length) return Math.min(Math.max(alvo, minAbs), maxAbs);
  const comPonto = dentro.filter(s => fechaIdeia(s.text));
  const lista = comPonto.length ? comPonto : dentro;
  let melhor = lista[0], menorDist = Infinity;
  for (const s of lista) {
    const d = Math.abs(s.end - alvo);
    if (d < menorDist) { menorDist = d; melhor = s; }
  }
  return melhor.end;
}

// ============================================================
// LEGENDA DE FALA
// ============================================================
function limparAss(t) {
  return String(t || '').replace(/[{}\\]/g, '').replace(/\s+/g, ' ').trim();
}

// agrupa as palavras em linhas curtas de 1 linha só
function linhasKaraoke(ws) {
  const linhas = [];
  let atual = [];
  const fecha = () => { if (atual.length) { linhas.push(atual); atual = []; } };
  for (let i = 0; i < ws.length; i++) {
    const p = ws[i], ant = ws[i - 1];
    if (ant && p.start - ant.end >= KARAOKE_PAUSA_QUEBRA) fecha();
    const txt = atual.map(w => w.word).join(' ');
    if (atual.length >= KARAOKE_MAX_PALAVRAS ||
        (txt + ' ' + p.word).trim().length > KARAOKE_MAX_CHARS) fecha();
    atual.push(p);
    if (/[.!?]$/.test(String(p.word).trim())) fecha();
  }
  fecha();
  return linhas;
}

// eventos com \kf (varredura da cor, efeito CapCut)
function eventosKaraoke(ws, deslocamento) {
  const linhas = linhasKaraoke(ws);
  const out = [];
  for (let n = 0; n < linhas.length; n++) {
    const l = linhas[n], prox = linhas[n + 1];
    const ini = l[0].start - deslocamento;
    let fim = l[l.length - 1].end + KARAOKE_SOBRA - deslocamento;
    // nunca invadir a linha seguinte: duas linhas na mesma posição empilhariam
    if (prox) fim = Math.min(fim, prox[0].start - deslocamento - 0.01);
    if (fim <= ini + 0.05) continue;
    let texto = '';
    for (let i = 0; i < l.length; i++) {
      const p = l[i], px = l[i + 1];
      const fimRel = fim + deslocamento;
      const ate = px ? Math.min(px.start, fimRel) : Math.min(p.end, fimRel);
      const cs = Math.max(6, Math.round((ate - p.start) * 100));
      texto += `{\\kf${cs}}${limparAss(p.word)} `;
    }
    out.push({ ini: Math.max(0, ini), fim, texto: texto.trim() });
  }
  return out;
}

// fallback (vídeo traduzido): sem karaokê, porque traduzir muda a
// quantidade e a ordem das palavras e destrói o tempo por palavra.
// Segmento longo é quebrado em pedaços de no máximo 2 linhas, com o
// tempo do segmento dividido proporcionalmente ao tamanho do pedaço.
function quebrarTexto(t, max) {
  const palavras = t.split(' ');
  const partes = [];
  let atual = '';
  for (const p of palavras) {
    if (atual && (atual + ' ' + p).length > max) { partes.push(atual); atual = p; }
    else atual = atual ? atual + ' ' + p : p;
  }
  if (atual) partes.push(atual);
  return partes;
}

function eventosSegmento(segs, deslocamento, ini0, fim0) {
  const out = [];
  for (const s of segs) {
    if (s.end <= ini0 || s.start >= fim0) continue;
    const ini = Math.max(0, s.start - deslocamento);
    const fim = Math.min(s.end, fim0) - deslocamento;
    if (fim <= ini + 0.05) continue;
    const t = limparAss(s.text);
    if (!t) continue;

    const partes = quebrarTexto(t, LEGENDA_MAX_CHARS_SEG);
    const totalChars = partes.reduce((a, p) => a + p.length, 0) || 1;
    let cursor = ini;
    for (let k = 0; k < partes.length; k++) {
      const fatia = (fim - ini) * (partes[k].length / totalChars);
      let fimParte = (k === partes.length - 1) ? fim : cursor + fatia;
      if (fimParte - cursor < LEGENDA_MIN_SEG && k < partes.length - 1) {
        fimParte = Math.min(fim, cursor + LEGENDA_MIN_SEG);
      }
      if (fimParte > cursor + 0.05) out.push({ ini: cursor, fim: fimParte, texto: partes[k] });
      cursor = fimParte;
      if (cursor >= fim) break;
    }
  }
  return out;
}

// ============================================================
function limpar(t, max) {
  return (t || '').toString()
    .replace(/[{}]/g, '').replace(/\\/g, '')
    .replace(/[\r\n]+/g, ' ').replace(/["`$]/g, '')
    .replace(/\s+/g, ' ').trim().slice(0, max || 90);
}
function nomeArquivoSeguro(t) {
  return (t || '').toString()
    .replace(/[\\/:*?"<>|]/g, '-').replace(/\s+/g, ' ').trim().slice(0, 60);
}
function tempoAss(s) {
  s = Math.max(0, s);
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), seg = s % 60;
  return `${h}:${String(m).padStart(2, '0')}:${seg.toFixed(2).padStart(5, '0')}`;
}

// ---- 1) ordena ----
const ordenados = [...parsed.cortes].sort(
  (a, b) => Number(a.inicio_seg) - Number(b.inicio_seg)
);

// ---- 2) alinha à fala + garante duração ----
const limite = duracaoTotal || Infinity;
let fimAnterior = 0;
const ajustados = [];
for (const c of ordenados) {
  const pedidoIni = Math.max(0, Number(c.inicio_seg));
  const pedidoFim = Number(c.fim_seg);
  const inicio = alinharInicio(Math.max(pedidoIni, fimAnterior), fimAnterior);
  const minAbs = Math.min(inicio + MIN_DURACAO, limite);
  const maxAbs = Math.min(inicio + MAX_DURACAO, limite);
  const alvoFim = Math.max(pedidoFim, minAbs);
  let fim = alinharFim(alvoFim, minAbs, maxAbs) + FOLGA_FIM;
  if (fim > limite) fim = limite;
  const duracao = fim - inicio;
  if (duracao < MIN_DURACAO * 0.9) continue;
  fimAnterior = fim;
  ajustados.push({ ...c, inicio_seg: inicio, fim_seg: fim, duracao_seg: duracao });
}
if (ajustados.length === 0) {
  throw new Error(
    `Nenhum corte atingiu ${MIN_DURACAO}s dentro dos ${duracaoTotal.toFixed(0)}s do vídeo.`
  );
}

// ---- 3) legenda + comando ----
return ajustados.map((c, i) => {
  const indice = i + 1;
  const total = ajustados.length;
  const inicio = c.inicio_seg;
  const fimAbs = c.fim_seg;
  const duracao = c.duracao_seg;

  const hook = limpar(c.hook || c.titulo, 60);
  const titulo = limpar(c.titulo, 70);
  const meio = limpar(c.texto_meio, 60);
  const pergunta = limpar(c.pergunta_final, 70);

  const arquivoSaida = `${PASTA}/${videoId}_parte${indice}.mp4`;
  const arquivoAss = `${PASTA}/${videoId}_parte${indice}.ass`;

  const fimClipe = duracao;
  const hookAte = TEXTO_TOPO_FIXO ? fimClipe : Math.min(HOOK_ATE, duracao * 0.15);
  const meioInicio = duracao * MEIO_INICIO_PCT;
  const perguntaInicio = Math.max(meioInicio + MEIO_DURACAO + 1, duracao - PERGUNTA_ANTES_FIM);

  const fade = `\\fad(${FADE_ENTRA},${FADE_SAI})`;
  const pop = POP_HOOK
    ? `\\fscx${POP_ESCALA}\\fscy${POP_ESCALA}\\t(0,${POP_MS},\\fscx100\\fscy100)`
    : '';

  const eventos = [];
  const D = (ini, fim, estilo, texto, efeito) =>
    `Dialogue: 0,${tempoAss(ini)},${tempoAss(fim)},${estilo},,0,0,0,,{${efeito === '' ? '' : (efeito || fade)}}${texto}`;

  if (MOSTRAR_SELO_PARTE) eventos.push(D(0, fimClipe, 'Parte', `PARTE ${indice}/${total}`));
  eventos.push(D(0, hookAte, 'Hook', hook, fade + pop));
  if (!TEXTO_TOPO_FIXO && titulo && titulo !== hook) {
    eventos.push(D(hookAte, fimClipe, 'Titulo', titulo));
  }
  if (MOSTRAR_TEXTO_MEIO && meio) {
    eventos.push(D(meioInicio, meioInicio + MEIO_DURACAO, 'Meio', meio));
  }
  if (pergunta && perguntaInicio < fimClipe) {
    eventos.push(D(perguntaInicio, fimClipe, 'Pergunta', pergunta));
  }

  // --- legenda de fala dentro da janela do corte ---
  let modoLegenda = 'nenhuma';
  if (LEGENDA_FALA) {
    if (usarKaraoke) {
      const dentro = palavras.filter(p => p.start >= inicio - 0.05 && p.end <= fimAbs + 0.3);
      const evs = eventosKaraoke(dentro, inicio);
      for (const e of evs) {
        if (e.ini >= fimClipe) continue;
        eventos.push(`Dialogue: 0,${tempoAss(e.ini)},${tempoAss(Math.min(e.fim, fimClipe))},Fala,,0,0,0,,${e.texto}`);
      }
      modoLegenda = `karaokê (${evs.length} linhas)`;
    } else {
      const evs = eventosSegmento(segmentos, inicio, inicio, fimAbs);
      for (const e of evs) {
        if (e.ini >= fimClipe) continue;
        eventos.push(D(e.ini, Math.min(e.fim, fimClipe), 'Fala', e.texto, ''));
      }
      modoLegenda = `por segmento (${evs.length} linhas)`;
    }
  }

  const ass = [
    '[Script Info]',
    'ScriptType: v4.00+',
    `PlayResX: ${LARGURA}`,
    `PlayResY: ${ALTURA}`,
    'WrapStyle: 0',
    'ScaledBorderAndShadow: yes',
    '',
    '[V4+ Styles]',
    'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',
    `Style: Parte,${FONTE_NOME},${FONT_PARTE},&H00FFFFFF,&H00FFFFFF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,3,4,0,8,40,40,${TOPO_PARTE},1`,
    `Style: Hook,${FONTE_NOME},${FONT_HOOK},${COR_HOOK},${COR_HOOK},&H00000000,&H${CAIXA}000000,-1,0,0,0,100,100,0,0,3,8,3,8,45,45,${TOPO_TEXTO},1`,
    `Style: Titulo,${FONTE_NOME},${FONT_TITULO},${COR_TITULO},${COR_TITULO},&H00000000,&H${CAIXA}000000,-1,0,0,0,100,100,0,0,3,6,2,8,45,45,${TOPO_TEXTO},1`,
    `Style: Fala,${FONTE_NOME},${usarKaraoke ? FONT_FALA : FONT_FALA_SEG},${usarKaraoke ? COR_FALA_DITA : COR_FALA_ANTES},${COR_FALA_ANTES},&H00000000,&H${CAIXA}000000,-1,0,0,0,100,100,0,0,3,5,2,2,145,145,${BAIXO_FALA},1`,
    `Style: Meio,${FONTE_NOME},${FONT_MEIO},${COR_MEIO},${COR_MEIO},&H00000000,&H${CAIXA}000000,-1,0,0,0,100,100,0,0,3,6,2,2,145,145,${BAIXO_MEIO},1`,
    `Style: Pergunta,${FONTE_NOME},${FONT_PERGUNTA},${COR_PERGUNTA},${COR_PERGUNTA},&H00000000,&H${CAIXA}000000,-1,0,0,0,100,100,0,0,3,6,2,2,145,145,${BAIXO_PERGUNTA},1`,
    '',
    '[Events]',
    'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text',
    ...eventos
  ].join('\n');

  const filtro =
    `[0:v]split=2[bg][fg];` +
    `[bg]scale=${LARGURA}:${ALTURA}:force_original_aspect_ratio=increase,` +
    `crop=${LARGURA}:${ALTURA},gblur=sigma=${BLUR_FUNDO}[bgb];` +
    `[fg]scale=${LARGURA}:-2[fgs];` +
    `[bgb][fgs]overlay=(W-w)/2:(H-h)/2,` +
    `subtitles=filename=${arquivoAss}:fontsdir=${PASTA_FONTES}[v]`;

  const comando =
    `cat > ${arquivoAss} <<'ASSEOF'\n${ass}\nASSEOF\n` +
    `ffmpeg -y -ss ${inicio.toFixed(2)} -t ${duracao.toFixed(2)} -i ${PASTA}/${videoId}.mp4 ` +
    `-filter_complex "${filtro}" -map "[v]" -map 0:a? ` +
    `-c:v libx264 -preset veryfast -crf 23 -pix_fmt yuv420p -r 30 ` +
    `-c:a aac -b:a 128k -movflags +faststart ${arquivoSaida}`;

  return {
    json: {
      indice, total_partes: total,
      inicio_seg: inicio, fim_seg: c.fim_seg, duracao_seg: duracao,
      titulo: c.titulo, hook, texto_meio: meio, pergunta_final: pergunta,
      descricao: c.descricao,
      legenda: modoLegenda, traduzido: foiTraduzido,
      arquivo_saida: arquivoSaida, arquivo_ass: arquivoAss,
      nome_arquivo: `Parte ${indice} - ${nomeArquivoSeguro(c.titulo)}.mp4`,
      comando_ffmpeg: comando
    }
  };
});

