// Substitui o texto de cada segmento pela tradução, MANTENDO os tempos
// originais do Whisper — é isso que preserva a sincronia.
const original = $('Montar transcrição c/ timestamps').first().json;
const bruto = $input.first().json;

let conteudo = bruto?.choices?.[0]?.message?.content;
if (!conteudo) throw new Error('A tradução não voltou conteúdo: ' + JSON.stringify(bruto).slice(0, 300));

let traduzidos;
try {
  const obj = typeof conteudo === 'string' ? JSON.parse(conteudo) : conteudo;
  traduzidos = obj.segmentos || obj.segments || [];
} catch (e) {
  throw new Error('A tradução não voltou JSON válido: ' + String(conteudo).slice(0, 300));
}

const porIndice = new Map(traduzidos.map(s => [Number(s.i), String(s.t ?? '')]));
const faltando = [];

const segmentos = original.segmentos.map((s, i) => {
  const t = porIndice.get(i);
  if (t === undefined || !t.trim()) { faltando.push(i); return s; }   // sem tradução: fica o original
  return { start: s.start, end: s.end, text: t.trim() };
});

// tolera até 2 buracos sempre, e 20% em vídeo longo
if (faltando.length > Math.max(2, original.segmentos.length * 0.2)) {
  throw new Error(`A tradução devolveu ${traduzidos.length} de ${original.segmentos.length} segmentos — descartei para não publicar legenda quebrada.`);
}

const linhas = segmentos.map(s => `[${s.start.toFixed(1)}-${s.end.toFixed(1)}] ${s.text}`);

return [{
  json: {
    ...original,
    transcricao_com_tempo: linhas.join('\n'),
    segmentos,
    palavras: [],          // traduzir destrói o tempo por palavra: sem karaokê
    traduzido: true,
    idioma_origem: original.idioma,
    segmentos_sem_traducao: faltando.length
  }
}];

// Ponto único de entrada dos dois caminhos (português direto ou traduzido).
// Tudo depois do agente lê daqui, então nada precisa saber qual caminho rodou.
const j = $input.first().json;
return [{
  json: {
    ...j,
    traduzido: !!j.traduzido,
    modo_legenda: (!j.traduzido && (j.palavras || []).length) ? 'karaokê' : 'por segmento'
  }
}];
